import heapq

def main():
    N, M = map(int, input().split())
    graph = [[] for _ in range(N)]
    for _ in range(M):
        l, d, k, c, a, b = map(int, input().split())
        a -= 1
        b -= 1
        graph[b].append((a, l, d, k, c))

    inf = float('inf')
    time = [-inf] * N
    time[N-1] = inf
    queue = [(inf, N-1)]

    while queue:
        tx, x = heapq._heappop_max(queue)
        if time[x] < tx:
            for y, l, d, k, c in graph[x]:
                if tx >= l + c:
                    if l + (k-1) * d + c <= tx:
                        ty = l + (k-1) * d
                    else:
                        ty = tx - (tx - c - l) % d
                    if time[y] < ty:
                        time[y] = ty
                        heapq._heappush_max(queue, (ty, y))

    for i in range(N-1):
        ans = time[i]
        if ans == -inf:
            ans = "Unreachable"
        print(ans)
